import { chapter } from "./resource-chapter";

type Check = [string, string, string, string, string];
type SqlTopic = {
  id: string;
  title: string;
  summary: string;
  content: [string, string];
  examples: [string, string, string];
  checks: [Check, Check, Check];
  level?: "Beginner" | "Intermediate" | "Advanced";
};

function topics(section: string, items: SqlTopic[]) {
  return chapter(section, items.map(({ checks, examples, ...lesson }) => ({
    ...lesson,
    level: lesson.level ?? "Beginner",
    examples: examples.map((code, index) => ({ title: `Example ${index + 1}`, code, result: "Run the statement on a small sample table and inspect the returned rows or changed data." })),
    quizzes: checks.map(([question, correct, wrongA, wrongB, explanation]) => ({ question, options: [correct, wrongA, wrongB], answer: 0, explanation })),
  })));
}

type Extra = [string,string,string,string,string,string,string,string,string,string,string];
function extras(section: string, items: Extra[]) {
  return chapter(section, items.map(([id,title,summary,detail,a,b,c,correct,wrongA,wrongB,why]) => ({
    id,title,summary,content:[detail,`Practice each query against a small dataset and check its result before using it in an application. SQL support differs among database engines, so confirm the dialect when adapting syntax.`],
    level:"Intermediate" as const,
    examples:[a,b,c].map((code,index)=>({title:`Example ${index+1}`,code,result:"Inspect the rows returned or the schema/data change made by this statement."})),
    quizzes:[
      {question:`What is the main purpose of ${title}?`,options:[correct,wrongA,wrongB],answer:0,explanation:why},
      {question:`Which statement about ${title} is accurate?`,options:[correct,wrongB,wrongA],answer:0,explanation:why},
      {question:`When using ${title}, what should you remember?`,options:[correct,wrongA,wrongB],answer:0,explanation:why},
    ],
  })));
}

export const sqlLessons = [
  ...topics("SQL Foundations", [
    { id:"sql-intro", title:"What SQL Does", summary:"Use SQL to describe how a relational database should read or change structured records.", content:["SQL is a language for working with data organized in tables. A query states the result you wantâ€”such as selected columns, matching rows, or grouped totalsâ€”and the database executes that request.","SQL is standardized, but engines differ in features and syntax. Lessons use SQLite-friendly examples where possible and label engine-specific statements instead of treating every database as identical."], examples:["SELECT name FROM learners;","INSERT INTO learners (name) VALUES ('Ari');","SELECT course_id, COUNT(*) FROM enrollments GROUP BY course_id;"], checks:[["What is SQL mainly used for?","Querying and managing structured database data","Styling a web page","Sending browser animations","SQL statements read or change data in database systems."],["What does a relational database organize records into?","Tables with rows and columns","Folders of image pixels","A single unstructured paragraph","Tables model records using columns and rows."],["Do all database engines support exactly the same syntax?","No; features and details vary by engine","Yes, every feature is identical","Only column names vary","SQL dialects share a foundation but differ in capabilities."]] },
    { id:"sql-syntax", title:"SQL Statement Shape and Syntax", summary:"Write readable statements with keywords, identifiers, values, commas, and semicolons.", content:["A query is built from clauses such as SELECT, FROM, WHERE, and ORDER BY. Keywords describe the operation; identifiers name tables and columns; quoted literals represent text values.","SQL keywords are commonly written in uppercase for readability, though SQLite accepts many keywords in other cases. Use single quotes for text values, commas between items, and a semicolon to mark the end of a statement."], examples:["SELECT name, score FROM learners;","SELECT title\nFROM courses\nWHERE published = 1;","INSERT INTO courses (title, published)\nVALUES ('SQL Basics', 1);"], checks:[["Which marks a text literal in common SQL syntax?","Single quotes","Square brackets","A dollar sign before each word","Text values are normally enclosed in single quotes."],["What separates columns in a SELECT list?","Commas","Colons","Slashes","Commas separate expressions in a list."],["Why format a query across multiple lines?","To make clauses easier to scan","To change its data types","To force rows into a new order","Whitespace improves readability without changing query meaning."]] },
    { id:"sql-data-types", title:"SQL Data Types", summary:"Choose column types that fit the values and operations a table needs.", content:["Types describe what a column stores, such as whole numbers, decimal values, text, or date/time values. Good choices make constraints and calculations clearer.","Type names and enforcement differ across engines. SQLite uses type affinity and accepts several storage classes; other engines may enforce declared types more strictly. Match examples to the database you are using."], examples:["CREATE TABLE inventory (sku TEXT, quantity INTEGER);","CREATE TABLE invoices (amount NUMERIC, created_at TEXT);","CREATE TABLE settings (enabled INTEGER NOT NULL DEFAULT 0);"], checks:[["What is a column data type for?","Describing the kind of value a column stores","Sorting rows by itself","Creating a login account","Types communicate the intended values and operations."],["Should type syntax be assumed identical across engines?","No; type names and rules can differ","Yes, including all date formats","Only table names differ","Engine documentation and behavior differ."],["What is a useful type for a whole-number quantity?","An integer type","A binary image type","A JSON document in every case","Whole-number counts are naturally represented by an integer type."]] },
    { id:"sql-keywords", title:"SQL Keywords and Identifiers", summary:"Recognize command words and name database objects clearly.", content:["Keywords such as SELECT and WHERE express query structure. Identifiers are your table, column, constraint, and index names. Choose names that explain the data they represent.","Avoid reserved words for identifiers when practical. If a name must be quoted, follow the quoting style of the database engine; SQLite uses double quotes for identifiers, while other engines may allow additional forms."], examples:["SELECT learner_name FROM learners;","CREATE TABLE course_catalog (course_id INTEGER, title TEXT);","SELECT \"order\" FROM order_items;"], checks:[["What is an identifier?","A name for a table or column","A value returned by COUNT","A query result row","Identifiers name database objects."],["Why avoid reserved keywords as table names?","They can conflict with SQL syntax","They automatically encrypt rows","They prevent all indexes","Reserved words can make statements ambiguous or require quoting."],["What is a good naming habit?","Use clear names that explain the data","Use a random short name for every column","Reuse a name for unrelated meanings","Meaningful identifiers make queries easier to maintain."]] },
    { id:"sql-comments", title:"SQL Comments", summary:"Annotate query intent with comments that the database ignores as executable instructions.", content:["Comments help explain why a query uses a condition or join. A line comment begins with two hyphens; a block comment is wrapped between slash-star and star-slash.","Comments do not replace clear names or safe query construction. Never concatenate user input into a query just because the statement contains comments."], examples:["-- Return only active learners\nSELECT name FROM learners WHERE active = 1;","/* Count distinct courses */\nSELECT COUNT(DISTINCT course_id) FROM enrollments;","SELECT id -- stable row identifier\nFROM learners;"], checks:[["Which token begins a common SQL line comment?","--","##","\\","Two hyphens start a SQL line comment in common dialects."],["What is a block comment used for?","Notes spanning part of a statement or multiple lines","A constraint on table width","A transaction commit","Block comments allow longer annotations."],["Do comments make unsafe input concatenation safe?","No","Yes, automatically","Only in SELECT queries","Comments do not change how input is handled or escaped."]] },
    { id:"sql-operators", title:"SQL Operators", summary:"Combine comparisons, arithmetic, and logical conditions to shape a query.", content:["Comparison operators test values, arithmetic operators calculate numeric expressions, and logical operators combine predicates. Parentheses make complex condition order explicit.","SQL uses three-valued logic around NULL: comparisons with NULL are unknown rather than true or false. Use IS NULL when checking missing values."], examples:["SELECT price * quantity AS line_total FROM order_lines;","SELECT * FROM learners WHERE score >= 80 AND active = 1;","SELECT * FROM tasks WHERE (status = 'open' OR status = 'blocked') AND priority > 1;"], checks:[["What does AND require?","Both conditions to be true","At least one condition to be true","No condition to be evaluated","AND combines predicates that must all match."],["How should a query check for a missing value?","Use IS NULL","Use = NULL","Use LIKE NULL","NULL needs the IS NULL predicate."],["What improves clarity in a mixed AND/OR condition?","Parentheses","Removing all spaces","Changing column names to keywords","Parentheses make intended logic grouping explicit."]] },
    { id:"sql-select", title:"Selecting Columns with SELECT", summary:"Choose the fields and expressions returned by a query.", content:["SELECT names the values to return, and FROM identifies their source table. Prefer specific columns over SELECT * in queries you expect to maintain.","Aliases can label calculated expressions. A SELECT query reads data; it does not change the stored rows."], examples:["SELECT name, email FROM learners;","SELECT title FROM courses;","SELECT price, quantity, price * quantity AS total FROM order_lines;"], checks:[["Which clause names returned columns?","SELECT","WHERE","HAVING","SELECT defines the output expressions."],["Which clause identifies the source table?","FROM","ORDER BY","LIMIT","FROM names the data source."],["Does SELECT by itself update stored rows?","No","Yes, it replaces every row","Only when it contains a string","SELECT retrieves a result without modifying source data."]] },
    { id:"sql-select-distinct", title:"Removing Duplicate Results with DISTINCT", summary:"Return unique combinations of selected column values.", content:["DISTINCT removes duplicate result rows based on the complete selected expression list. Selecting two columns means uniqueness is evaluated for the pair, not each column separately.","Use it when uniqueness is the question being asked. It may require extra work, so avoid adding DISTINCT as a blanket fix for a join that multiplies rows unexpectedly."], examples:["SELECT DISTINCT country FROM learners;","SELECT DISTINCT course_id, learner_id FROM enrollments;","SELECT COUNT(DISTINCT learner_id) FROM enrollments;"], checks:[["What does DISTINCT compare?","The selected result values as a row","Every column in every database table","Only the first source row","Duplicate output rows are removed based on selected expressions."],["With two selected columns, what counts as a duplicate?","A row where both selected values match","A row where either value matches","Any row with a NULL","Uniqueness applies to the selected combination."],["Should DISTINCT hide a faulty join?","No, inspect the join relationship first","Yes, always append it","Only on primary-key tables","Unexpected duplicates may indicate a join cardinality problem."]] },
    { id:"sql-where", title:"Filtering Rows with WHERE", summary:"Keep rows that satisfy a condition before grouping or sorting the result.", content:["WHERE evaluates a predicate for each source row. Comparisons, logical combinations, IN, BETWEEN, and pattern checks can express common filters.","Filter precisely and preview a condition with SELECT before using the same predicate in an UPDATE or DELETE. WHERE does not filter aggregate groups; HAVING does that later."], examples:["SELECT name FROM learners WHERE active = 1;","SELECT title FROM courses WHERE level = 'beginner' AND published = 1;","SELECT * FROM invoices WHERE amount >= 100;"], checks:[["What does WHERE filter?","Source rows","Output column names","Database schemas","WHERE selects rows matching a predicate."],["When does WHERE apply relative to grouping?","Before groups are formed","After ORDER BY","Only after LIMIT","WHERE filters rows before GROUP BY aggregation."],["What should you do before a destructive statement's WHERE?","Preview the condition with SELECT","Remove the condition to simplify it","Replace it with ORDER BY","A preview helps confirm exactly which rows match."]] },
    { id:"sql-order-by", title:"Sorting Results with ORDER BY", summary:"Sort query results by one or more columns and choose each direction explicitly.", content:["ORDER BY sorts the result set. ASC is the default ascending order; DESC sorts descending. Add a second key to break ties consistently.","Without ORDER BY, row order is not guaranteed. Use a stable tie-breaker such as an ID when pagination or repeatable output matters."], examples:["SELECT name FROM learners ORDER BY name ASC;","SELECT title, created_at FROM courses ORDER BY created_at DESC;","SELECT category, score FROM results ORDER BY category ASC, score DESC;"], checks:[["What is the default ORDER BY direction?","Ascending","Descending","Random","ASC is the usual default."],["What makes tied results deterministic?","Add a stable secondary sort key","Use SELECT DISTINCT","Remove the ORDER BY clause","A tie-breaker defines order among equal primary sort values."],["Can you rely on row order without ORDER BY?","No","Yes, primary keys always sort automatically","Only for the first query","Relational results have no guaranteed order unless requested."]] },
    { id:"sql-and", title:"Combining Conditions with AND", summary:"Require multiple predicates to match the same row.", content:["AND returns rows only when every combined condition is true. It is useful for narrowing by multiple attributes, such as an active status plus a minimum score.","Use parentheses when mixing AND with OR so the grouping reflects your intent. Check NULL behavior because unknown comparisons are not true."], examples:["SELECT * FROM learners WHERE active = 1 AND score >= 80;","SELECT * FROM products WHERE category = 'books' AND price < 25;","SELECT * FROM tasks WHERE owner_id = 7 AND status = 'open' AND priority > 1;"], checks:[["What must be true for A AND B to match?","Both A and B","Either A or B","Neither A nor B","AND requires all combined predicates to be true."],["How do parentheses help with AND?","They clarify grouping when conditions are mixed","They automatically sort rows","They make NULL equal to zero","Grouping is explicit with parentheses."],["Does a NULL comparison count as true for AND?","No","Always yes","Only when the other condition is false","Unknown does not satisfy a WHERE predicate."]] },
    { id:"sql-or", title:"Combining Alternatives with OR", summary:"Match a row when at least one of several alternative conditions is true.", content:["OR is useful for alternatives such as several accepted statuses or categories. Group alternatives with parentheses when they are combined with additional AND conditions.","A missing set of parentheses can change the meaning because AND and OR have precedence rules. Write the intended grouping explicitly for complex predicates."], examples:["SELECT * FROM tickets WHERE status = 'open' OR status = 'waiting';","SELECT * FROM learners WHERE city = 'Pune' OR city = 'Jaipur';","SELECT * FROM products WHERE (category = 'books' OR category = 'games') AND in_stock = 1;"], checks:[["What does A OR B require?","At least one predicate to be true","Both predicates to be true","Every row to be false","OR matches either alternative."],["Why parenthesize OR alternatives with another condition?","To make the intended grouping clear","To turn OR into a join","To create an index","Explicit grouping avoids precedence mistakes."],["What can happen if parentheses are omitted?","AND/OR precedence may change the intended result","The query becomes a stored procedure","Rows are encrypted","Operator precedence affects the logical result."]] },
    { id:"sql-not", title:"Negating Conditions with NOT", summary:"Invert a predicate to exclude matching values while accounting for NULL.", content:["NOT reverses a Boolean condition. It pairs with predicates such as IN and EXISTS to express exclusion.","NULL is neither an ordinary value nor equal to another NULL. A NOT condition involving unknown results may still be unknown, so handle missing values explicitly."], examples:["SELECT * FROM learners WHERE NOT active = 1;","SELECT * FROM courses WHERE category NOT IN ('archived', 'draft');","SELECT * FROM learners WHERE email IS NOT NULL;"], checks:[["What does NOT do to a predicate?","Inverts its truth result","Sorts the matching rows","Removes a column","NOT negates a Boolean condition."],["How do you test that a value exists rather than being NULL?","IS NOT NULL","!= NULL","NOT = NULL","IS NOT NULL is the null-check predicate."],["Is NULL treated like a normal value by NOT?","No, NULL comparisons can be unknown","Yes, NULL is always zero","Yes, NULL equals an empty string","SQL uses three-valued logic for NULL."]] },
  ]),
  ...topics("Filtering and Changing Rows", [
    { id:"sql-insert-into", title:"Adding Rows with INSERT INTO", summary:"Add records by naming target columns and supplying matching values.", content:["INSERT INTO creates new rows. Listing the target columns makes the statement resilient when the table schema gains another field.","Use bound parameters in application code instead of building SQL by joining user-provided strings. Verify constraints and defaults before inserting batches."], examples:["INSERT INTO learners (name, active) VALUES ('Mira', 1);","INSERT INTO categories (label) VALUES ('Design');","INSERT INTO enrollments (learner_id, course_id) VALUES (12, 4);"], checks:[["Why name columns in INSERT?","It makes value-to-column mapping explicit","It disables table constraints","It sorts inserted rows","Explicit target columns reduce accidental mapping errors."],["How should an application insert user-provided text?","With bound parameters","By concatenating it into SQL","By placing it in a comment","Bound parameters separate values from SQL syntax."],["What should you check before inserting?","Required columns, defaults, and constraints","The browser's screen width","The ORDER BY clause","Schema rules determine which rows can be inserted."]] },
    { id:"sql-null-values", title:"Understanding NULL Values", summary:"Represent missing or unknown information and test it with null predicates.", content:["NULL means a value is missing or unknown; it is not the same as zero, false, or an empty string. Ordinary equality comparisons with NULL do not behave like comparisons between known values.","Use IS NULL and IS NOT NULL. Aggregates such as COUNT(column) ignore NULL values, while COUNT(*) counts rows."], examples:["SELECT * FROM learners WHERE graduation_year IS NULL;","SELECT COALESCE(phone, 'Not provided') FROM contacts;","SELECT COUNT(phone), COUNT(*) FROM contacts;"], checks:[["How should a query find missing values?","IS NULL","= NULL","LIKE ''","IS NULL tests for a missing SQL value."],["Is NULL the same as an empty string?","No","Yes, in every engine","Only in numeric columns","An empty string is a present text value; NULL is missing/unknown."],["What does COUNT(column) generally ignore?","NULL values","Duplicate values automatically","Rows with zero","COUNT(expression) counts non-NULL results."]] },
    { id:"sql-update", title:"Changing Rows with UPDATE", summary:"Modify existing records and use a precise WHERE condition to target them.", content:["UPDATE sets one or more columns on rows in a table. Without WHERE, every row may be changed, so inspect the target predicate before running a change.","For critical multi-step changes, use a transaction and verify the affected row count. Parameters should carry external values safely."], examples:["UPDATE learners SET active = 0 WHERE id = 42;","UPDATE products SET price = price * 1.05 WHERE category = 'stationery';","UPDATE tasks SET status = 'done', completed_at = '2026-01-10' WHERE id = 9;"], checks:[["What can UPDATE without WHERE do?","Change every row in the table","Change no rows","Create an index","An UPDATE with no filter applies to all rows."],["What should you verify before UPDATE?","The rows matching its WHERE clause","The CSS class of the form","The count of selected columns","Previewing the target rows reduces accidental changes."],["How should an app supply values to UPDATE?","Bound parameters","SQL string concatenation","A SQL comment","Parameters safely separate values from query syntax."]] },
    { id:"sql-delete", title:"Removing Rows with DELETE", summary:"Delete matching records carefully and distinguish row deletion from table removal.", content:["DELETE removes rows from a table. A WHERE condition limits the target; omitting it deletes every row while leaving the table structure in place.","Preview the predicate with SELECT, consider foreign-key effects, and use a transaction when a deletion must be reversible until confirmed."], examples:["DELETE FROM sessions WHERE expires_at < '2026-01-01';","DELETE FROM cart_items WHERE cart_id = 27 AND product_id = 11;","DELETE FROM audit_events WHERE created_at < '2024-01-01';"], checks:[["What does DELETE without WHERE target?","Every row","Only the newest row","The table definition","An unfiltered DELETE removes all table rows."],["How is DELETE different from DROP TABLE?","DELETE removes rows; DROP removes the table object","They always do the same thing","DROP only removes selected rows","The table structure remains after DELETE."],["What is a safe first step before a broad delete?","Run a SELECT with the same filter","Remove the WHERE clause","Disable foreign keys","A preview reveals which records will match."]] },
    { id:"sql-select-top-limit", title:"Limiting the Number of Results", summary:"Return a manageable subset using the syntax supported by the database engine.", content:["SQLite and PostgreSQL commonly use LIMIT; SQL Server commonly uses TOP or OFFSET/FETCH. These forms are dialect-specific even though the goal is similar.","Always combine row limits with a meaningful ORDER BY when you need predictable top results. Without ordering, the chosen subset is not guaranteed to represent newest, highest, or first records."], examples:["SELECT name FROM learners ORDER BY score DESC LIMIT 5; -- SQLite/PostgreSQL","SELECT TOP 5 name FROM learners ORDER BY score DESC; -- SQL Server","SELECT name FROM learners ORDER BY score DESC LIMIT 5 OFFSET 10; -- page two"], checks:[["Which form works in SQLite for a row cap?","LIMIT","SELECT TOP","ROWCOUNT()","SQLite uses LIMIT for limiting returned rows."],["Why use ORDER BY with a limit?","To define which rows are selected first","To make every query faster","To change the column types","A limit without ordering does not define a predictable subset."],["Is TOP syntax universal across SQL engines?","No, it is dialect-specific","Yes, every engine uses TOP","Only text columns support it","Database engines use different row-limiting syntax."]] },
    { id:"sql-like", title:"Pattern Matching with LIKE", summary:"Find text values that match a simple wildcard pattern.", content:["LIKE compares text against a pattern. In common SQL patterns, percent matches any number of characters and underscore matches one character.","Case sensitivity and extra wildcard syntax vary by engine and collation. Use bound parameters when patterns include user-provided text."], examples:["SELECT name FROM learners WHERE name LIKE 'A%';","SELECT email FROM contacts WHERE email LIKE '%@example.org';","SELECT code FROM rooms WHERE code LIKE 'B_2';"], checks:[["What does % mean in a LIKE pattern?","Any sequence of characters","Exactly one character","A numeric digit only","Percent is the multi-character wildcard in standard LIKE patterns."],["What does underscore match?","One character","Any length of text","Only whitespace","Underscore represents a single-character wildcard."],["What may differ among engines for LIKE?","Case handling and collation behavior","The meaning of SELECT","Whether tables have rows","Comparison rules can depend on engine and collation."]] },
    { id:"sql-wildcards", title:"Using SQL Wildcards", summary:"Build precise LIKE patterns with multi-character and single-character placeholders.", content:["A wildcard represents unknown characters in a text pattern. Percent can match zero or more characters; underscore matches one character.","Escaping a literal wildcard is dialect-sensitive. When the search string comes from a user, bind it as a value and define how literal percent or underscore characters should be handled."], examples:["SELECT * FROM products WHERE sku LIKE 'BK-%';","SELECT * FROM rooms WHERE code LIKE 'A_';","SELECT * FROM files WHERE filename LIKE 'report%.csv';"], checks:[["Which wildcard can match zero or many characters?","%","_","#","Percent spans a sequence of any length."],["Which wildcard stands for one character?","_","%","*","Underscore represents one character in SQL LIKE patterns."],["How should a wildcard search value from a user be supplied?","As a bound parameter","By concatenating it into SQL text","As an identifier","Bound parameters protect query structure from user input."]] },
    { id:"sql-in", title:"Matching a Set with IN", summary:"Check whether a value matches any member of a list or subquery result.", content:["IN shortens a series of equality alternatives. It can accept literal values or the output of a subquery.","If a NOT IN list or subquery can contain NULL, the result may surprise you because SQL uses unknown comparisons. NOT EXISTS is often a safer anti-match pattern."], examples:["SELECT * FROM courses WHERE level IN ('beginner', 'intermediate');","SELECT * FROM orders WHERE customer_id IN (4, 8, 12);","SELECT * FROM learners WHERE id IN (SELECT learner_id FROM awards);"], checks:[["What does IN test?","Whether a value matches any candidate in a set","Whether a column is sorted","Whether a row has a NULL","IN is a membership test."],["Can IN use a subquery?","Yes","No, it only accepts strings","Only in UPDATE","A subquery can provide the candidate values."],["Why can NOT IN with NULL be tricky?","Unknown comparisons can prevent expected matches","NULL becomes a wildcard","It always deletes rows","NULL participates in SQL's three-valued logic."]] },
    { id:"sql-between", title:"Filtering Ranges with BETWEEN", summary:"Test whether a value lies within an inclusive lower and upper bound.", content:["BETWEEN includes both endpoints. It can make numeric or date range conditions easier to read.","For date-time values, inclusive upper bounds can accidentally omit later times on the final day. A half-open rangeâ€”greater than or equal to start and less than next boundaryâ€”is often safer."], examples:["SELECT * FROM products WHERE price BETWEEN 10 AND 25;","SELECT * FROM scores WHERE score NOT BETWEEN 0 AND 49;","SELECT * FROM events WHERE starts_at >= '2026-01-01' AND starts_at < '2026-02-01';"], checks:[["Are BETWEEN endpoints included?","Yes, both ends are included","No, both are excluded","Only the lower endpoint","BETWEEN is inclusive of its endpoints."],["Why use a half-open date-time range?","It safely includes all timestamps before the next period boundary","It removes all time values","It changes dates to text","A strict upper boundary avoids missing timestamps later on the last day."],["What is NOT BETWEEN?","A test outside the inclusive range","A way to ignore WHERE","A join operation","NOT BETWEEN negates the range test."]] },
    { id:"sql-null-functions", title:"Handling Missing Values in Expressions", summary:"Choose fallback values or conditional logic when a field may be NULL.", content:["COALESCE returns the first non-NULL argument and is widely supported. IFNULL, ISNULL, and NVL are engine-specific alternatives with different names or argument rules.","Do not replace missing values blindly: a fallback can affect sorting, averages, and business meaning. Keep the distinction between missing and actual zero or empty text when it matters."], examples:["SELECT COALESCE(phone, 'Not listed') FROM contacts;","SELECT COALESCE(discount, 0) * price FROM products;","SELECT CASE WHEN score IS NULL THEN 'Pending' ELSE CAST(score AS TEXT) END FROM results;"], checks:[["What does COALESCE return?","The first non-NULL argument","The last argument always","The number of NULLs","COALESCE selects the first available value."],["Are IFNULL and ISNULL identical everywhere?","No, names and behavior can vary by engine","Yes, including argument counts","They are SQL keywords for joins","Null-handling helper functions are dialect-specific."],["What should guide a fallback value?","The meaning of missing data in the application","A preference to remove every NULL","The order of table columns","A fallback should preserve the intended business meaning."]] },
    { id:"sql-case", title:"Conditional Values with CASE", summary:"Return a value based on ordered conditions inside a query.", content:["CASE evaluates conditions in order and returns the result for the first match. ELSE supplies a fallback; without it, unmatched rows produce NULL.","CASE is useful for labels, conditional totals, and controlled bucketing. It does not replace WHERE when the goal is to remove rows from the result."], examples:["SELECT name, CASE WHEN score >= 80 THEN 'Pass' ELSE 'Review' END AS result FROM learners;","SELECT SUM(CASE WHEN status = 'paid' THEN amount ELSE 0 END) FROM invoices;","SELECT CASE category WHEN 'book' THEN 'Reading' ELSE 'Other' END FROM products;"], checks:[["How does CASE choose a result?","The result for the first matching WHEN","The result for the last matching WHEN","A random result each time","CASE evaluates branches in order."],["What does ELSE provide?","A fallback for unmatched conditions","A table alias","A join key","ELSE handles rows that match no WHEN."],["Does CASE remove rows from a result?","No, use WHERE to filter rows","Yes, it always deletes nonmatching rows","Only inside INSERT","CASE computes a value; WHERE filters rows."]] },
  ]),
  ...extras("Summaries and Relationships", [
    ["sql-aggregates","Aggregate Functions","Summarize many rows into one result.","Aggregate functions calculate a summary from a set of rows. COUNT counts values or rows; SUM and AVG work with numeric values; MIN and MAX find boundary values. NULL values are generally ignored by these functions, except COUNT(*), which counts rows.","SELECT COUNT(*) FROM learners;","SELECT SUM(amount) FROM invoices WHERE status = 'paid';","SELECT AVG(score), MIN(score), MAX(score) FROM results;","COUNT(*) counts rows, including rows with NULL columns","COUNT(column) always counts NULL values","AVG returns a text label","COUNT(*) counts each row in its input."],
    ["sql-min","Finding the Smallest Value with MIN","Return the lowest non-NULL value in a set.","MIN returns the smallest value in the selected group. It works with numbers and can also compare text or dates according to the database's ordering rules.","SELECT MIN(price) FROM products;","SELECT department, MIN(salary) FROM staff GROUP BY department;","SELECT MIN(created_at) FROM events;","The smallest non-NULL value","The average value","The number of rows","MIN finds the lowest value in its group."],
    ["sql-max","Finding the Largest Value with MAX","Return the highest non-NULL value in a set.","MAX returns the greatest value under the database's comparison rules. Use GROUP BY when you need one maximum per category.","SELECT MAX(score) FROM results;","SELECT category, MAX(price) FROM products GROUP BY category;","SELECT MAX(published_at) FROM articles;","The largest non-NULL value","The count of all rows","The first inserted value","MAX returns the greatest value in the group."],
    ["sql-count","Counting Rows with COUNT","Count records or non-NULL values.","COUNT(*) counts rows. COUNT(column) counts only rows where that expression is not NULL, while COUNT(DISTINCT column) counts unique non-NULL values.","SELECT COUNT(*) FROM orders;","SELECT COUNT(phone) FROM contacts;","SELECT COUNT(DISTINCT category) FROM products;","COUNT(column) skips NULL values","COUNT(column) counts only NULL values","COUNT(*) counts unique values","COUNT(column) ignores NULL entries."],
    ["sql-sum","Adding Values with SUM","Calculate a total from numeric values.","SUM adds non-NULL numeric values and is often paired with GROUP BY for totals by category. Consider whether an empty set should display NULL or a fallback such as zero.","SELECT SUM(amount) FROM invoices;","SELECT learner_id, SUM(points) FROM awards GROUP BY learner_id;","SELECT COALESCE(SUM(quantity), 0) FROM stock_moves;","SUM adds numeric values","SUM sorts the rows","SUM counts distinct strings","SUM produces a numeric total."],
    ["sql-avg","Calculating an Average with AVG","Find the arithmetic mean of non-NULL numeric values.","AVG divides the sum of included numeric values by their count. NULL values do not contribute; zero does contribute, so missing and zero values have different effects.","SELECT AVG(score) FROM results;","SELECT course_id, AVG(duration_minutes) FROM lessons GROUP BY course_id;","SELECT ROUND(AVG(price), 2) FROM products;","NULL values are excluded, while zero is included","NULL is treated as the number one","AVG returns the largest value","AVG averages the non-NULL numeric inputs."],
    ["sql-group-by","Grouping Rows with GROUP BY","Produce one summary row for each group value.","GROUP BY partitions matching rows into groups before aggregate calculations. Select grouping columns and aggregate expressions so each output row has a clear meaning.","SELECT level, COUNT(*) FROM courses GROUP BY level;","SELECT learner_id, SUM(points) FROM awards GROUP BY learner_id;","SELECT DATE(created_at), COUNT(*) FROM visits GROUP BY DATE(created_at);","It forms groups for aggregate calculations","It changes table column types","It inserts missing records","GROUP BY collects rows with matching group values."],
    ["sql-having","Filtering Groups with HAVING","Keep or remove groups based on aggregate conditions.","HAVING filters grouped results after aggregation, such as groups with at least five rows. Use WHERE to filter individual source rows before grouping.","SELECT level, COUNT(*) FROM courses GROUP BY level HAVING COUNT(*) >= 3;","SELECT learner_id, SUM(points) AS total FROM awards GROUP BY learner_id HAVING total > 100;","SELECT category, AVG(price) FROM products GROUP BY category HAVING AVG(price) < 50;","HAVING filters groups after aggregation","HAVING runs before FROM","HAVING renames the table","HAVING applies conditions to grouped results."],
    ["sql-aliases","Naming Results with Aliases","Give columns and tables short, readable names within a query.","AS assigns a temporary name to a selected expression or table reference. Column aliases make calculated output easier to read; table aliases shorten qualified column references.","SELECT COUNT(*) AS learner_count FROM learners;","SELECT p.title, p.price FROM products AS p;","SELECT first_name || ' ' || last_name AS full_name FROM learners;","An alias labels a result or table reference in the query","An alias permanently renames a stored table","An alias encrypts a column","An alias is a temporary query name."],
    ["sql-joins","Joining Related Tables","Combine related data using a condition between tables.","A join combines rows from two sources according to a matching condition. Use qualified column names where names overlap, and check key uniqueness to avoid unexpected duplicate output.","SELECT l.name, e.course_id FROM learners l JOIN enrollments e ON e.learner_id = l.id;","SELECT o.id, c.name FROM orders o JOIN customers c ON c.id = o.customer_id;","SELECT p.title, c.label FROM products p JOIN categories c ON c.id = p.category_id;","The ON condition describes which rows match","A join always deletes unmatched database rows","A join changes a table into a view","The join condition defines row relationships."],
    ["sql-inner-join","INNER JOIN","Return pairs that match in both joined sources.","INNER JOIN emits a result only when its join condition matches a row on each side. Rows without a partner are left out of that result.","SELECT l.name,e.course_id FROM learners l INNER JOIN enrollments e ON e.learner_id=l.id;","SELECT o.id,c.name FROM orders o INNER JOIN customers c ON c.id=o.customer_id;","SELECT p.title,c.label FROM products p INNER JOIN categories c ON c.id=p.category_id;","Only matching row pairs are returned","Every left row is preserved","It combines tables without a condition","INNER JOIN returns matches from both sides."],
    ["sql-left-join","LEFT JOIN","Keep every left-side row and add matching right-side data when present.","LEFT JOIN preserves all rows from its left input. If no right-side row matches, right-side columns are NULL; a WHERE condition on those columns can accidentally remove those unmatched rows.","SELECT l.name,e.course_id FROM learners l LEFT JOIN enrollments e ON e.learner_id=l.id;","SELECT c.name,o.id FROM customers c LEFT JOIN orders o ON o.customer_id=c.id;","SELECT p.title,r.rating FROM products p LEFT JOIN reviews r ON r.product_id=p.id;","All rows from the left input remain","Only rows with a right-side match remain","All right rows remain","LEFT JOIN preserves the left-side rows."],
    ["sql-right-join","RIGHT JOIN and Portable Alternatives","Understand right-preserving joins and rewrite them for engines that lack them.","RIGHT JOIN preserves rows from the right input, including those without a left match. Support varies by engine; SQLite versions and other database products differ, so check the target dialect or swap table order and use LEFT JOIN.","-- Portable equivalent by swapping inputs\nSELECT c.name,o.id FROM orders o LEFT JOIN customers c ON c.id=o.customer_id;","-- RIGHT JOIN syntax where supported\nSELECT c.name,o.id FROM orders o RIGHT JOIN customers c ON c.id=o.customer_id;","-- Explicit left-preserving form\nSELECT r.label,l.id FROM left_items l LEFT JOIN right_items r ON r.id=l.right_id;","RIGHT JOIN preserves rows from its right input","RIGHT JOIN always preserves both sides","RIGHT JOIN groups aggregate rows","The right input is retained even without a match."],
    ["sql-full-join","FULL OUTER JOIN","Keep matched rows and unmatched rows from both sides.","FULL OUTER JOIN returns matches plus unmatched rows from either input, filling the missing side with NULL. Engine support varies; a union of left joins can be a fallback when the target lacks this feature.","SELECT a.id,b.note FROM a FULL OUTER JOIN b ON a.id=b.id;","SELECT a.id,b.note FROM a LEFT JOIN b ON a.id=b.id UNION SELECT a.id,b.note FROM b LEFT JOIN a ON a.id=b.id;","SELECT x.code,y.label FROM x FULL JOIN y ON x.code=y.code;","Unmatched rows from both inputs are included","Only matching rows are included","All rows are cross-multiplied","FULL OUTER JOIN preserves unmatched rows on both sides."],
    ["sql-self-join","Joining a Table to Itself","Compare related rows in one table using distinct aliases.","A self join treats one table as two query inputs. Aliases distinguish the roles, such as an employee and that employee's manager.","SELECT e.name,m.name AS manager FROM staff e LEFT JOIN staff m ON m.id=e.manager_id;","SELECT a.name,b.name FROM people a JOIN people b ON a.city=b.city AND a.id<b.id;","SELECT item.name,parent.name FROM categories item LEFT JOIN categories parent ON parent.id=item.parent_id;","Use separate aliases for each role","Duplicate the table in storage first","A self join is only for deleting rows","Aliases let one table play multiple query roles."],
    ["sql-union","Combining Results with UNION","Append compatible query results and remove duplicate rows.","UNION combines result sets with the same number of compatible columns in corresponding positions. It removes duplicate result rows, which may require extra work compared with UNION ALL.","SELECT email FROM students UNION SELECT email FROM mentors;","SELECT city FROM customers UNION SELECT city FROM suppliers;","SELECT id,label FROM old_items UNION SELECT id,label FROM new_items;","UNION removes duplicate result rows","UNION sorts by a chosen key automatically","UNION combines columns side by side","UNION appends rows and removes duplicates."],
    ["sql-union-all","Combining Results with UNION ALL","Append compatible result sets while keeping duplicate rows.","UNION ALL keeps every row from each query, including duplicates. Use it when duplicates are meaningful or when you know the inputs cannot overlap.","SELECT email FROM students UNION ALL SELECT email FROM mentors;","SELECT id FROM archive UNION ALL SELECT id FROM current_items;","SELECT city FROM branch_a UNION ALL SELECT city FROM branch_b;","It preserves duplicates","It removes every repeated row","It only works with numbers","UNION ALL preserves all input rows."],
    ["sql-exists","Testing Related Rows with EXISTS","Keep a row when a related subquery returns at least one result.","EXISTS checks whether its subquery finds any row. Correlated EXISTS queries can express relationships clearly without returning duplicate outer rows when several matches exist.","SELECT c.name FROM customers c WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id=c.id);","SELECT p.title FROM products p WHERE EXISTS (SELECT 1 FROM reviews r WHERE r.product_id=p.id);","SELECT l.name FROM learners l WHERE NOT EXISTS (SELECT 1 FROM enrollments e WHERE e.learner_id=l.id);","Whether the subquery returns any row","The sum of all subquery values","Whether the subquery has an ORDER BY","EXISTS tests for at least one row."],
    ["sql-any-all","ANY and ALL Comparisons","Compare a value with a set of values where the database supports these operators.","Some database engines support ANY or ALL with subqueries: ANY means at least one comparison succeeds; ALL means every comparison succeeds. Support and syntax vary, so portable code can often use EXISTS, MIN, or MAX with care.","-- SQL Server-style example\nSELECT name FROM products WHERE price > ANY (SELECT price FROM specials);","-- SQL Server-style example\nSELECT name FROM products WHERE price > ALL (SELECT price FROM specials);","-- Portable existence pattern\nSELECT p.name FROM products p WHERE EXISTS (SELECT 1 FROM specials s WHERE p.price>s.price);","ANY needs at least one matching comparison; ALL needs every comparison","ANY and ALL both always mean equality","They are available identically in every database","Their semantics and support vary by database."],
    ["sql-select-into","Creating a Table from Query Results","Copy query output into a newly created table in engines that support SELECT INTO.","SELECT INTO creates a table from a query result in some engines, including SQL Server. SQLite uses CREATE TABLE ... AS SELECT instead; the new table may not inherit all constraints or indexes.","-- SQLite\nCREATE TABLE active_learners AS SELECT * FROM learners WHERE active=1;","-- SQL Server\nSELECT * INTO active_learners FROM learners WHERE active=1;","-- SQLite summary copy\nCREATE TABLE course_counts AS SELECT course_id,COUNT(*) AS total FROM enrollments GROUP BY course_id;","SELECT INTO support is dialect-specific","Every engine uses the same syntax","It updates rows in place","Table-copy syntax differs across engines."],
    ["sql-insert-select","Inserting Query Results into a Table","Insert multiple rows selected from another query.","INSERT INTO ... SELECT copies query results into an existing target table. The selected expressions must align with the target columns in number and compatible type; add a WHERE clause when only some rows belong.","INSERT INTO archive (id,name) SELECT id,name FROM learners WHERE active=0;","INSERT INTO monthly_totals (month,total) SELECT month,SUM(amount) FROM payments GROUP BY month;","INSERT INTO names (name) SELECT display_name FROM imports WHERE valid=1;","The selected values must match the target columns","The target table is created automatically","Only one value can be inserted","INSERT SELECT inserts the selected rows into an existing table."],
  ]),
  ...extras("Database Design and Operations", [
    ["sql-create-database","Creating a Database","Create a database container using the syntax supported by your database engine.","Database creation is an administrative operation and is not portable across all engines. SQLite commonly creates or opens a database file through a connection rather than a CREATE DATABASE statement.","-- SQLite: open/create a file in your app\n-- database: learning.db","-- MySQL / SQL Server\nCREATE DATABASE learning;","-- PostgreSQL\nCREATE DATABASE learning;","SQLite typically creates its database as a file","CREATE DATABASE is identical in every engine","A database is created by SELECT","Database administration syntax depends on the engine."],
    ["sql-drop-database","Removing a Database","Understand database deletion and protect data before destructive operations.","Dropping a database permanently removes its schema and data. It is an administrative command with engine-specific availability; SQLite applications usually close and manage the database file instead.","-- SQL Server / MySQL\nDROP DATABASE learning;","-- Check the target and backup before removal\n-- DROP DATABASE learning;","-- SQLite: close connections, then remove the chosen file using app tooling","DROP DATABASE can permanently remove stored data","DROP DATABASE only hides one query result","It is always reversible","Dropping a database is destructive and often irreversible without a backup."],
    ["sql-backup-database","Backing Up Database Data","Choose a backup approach that fits the database engine and deployment.","A usable backup should be consistent, protected, and tested by restoring it. Engines provide different tools; for SQLite use its backup facilities or a safe file copy strategy that accounts for active connections and journal files.","-- SQLite CLI example\n.backup 'learning-backup.db'","-- PostgreSQL example\npg_dump learning > learning.sql","-- MySQL example\nmysqldump learning > learning.sql","A backup should be tested by restoring it","A backup is unnecessary if a query ran","Copying a live database file is always safe","Restore testing checks that the backup can actually be used."],
    ["sql-create-table","Creating Tables","Define columns and constraints for a new data structure.","CREATE TABLE declares a table schema, including column names, types, defaults, and constraints. Model a clear key and required fields before adding application data.","CREATE TABLE learners (id INTEGER PRIMARY KEY, name TEXT NOT NULL);","CREATE TABLE courses (id INTEGER PRIMARY KEY, title TEXT NOT NULL, level TEXT);","CREATE TABLE enrollments (learner_id INTEGER, course_id INTEGER, PRIMARY KEY (learner_id,course_id));","CREATE TABLE defines a table and its columns","CREATE TABLE sorts existing rows","CREATE TABLE runs a quiz","CREATE TABLE establishes a schema."],
    ["sql-drop-table","Removing Tables","Remove a table definition and its stored rows when that is truly intended.","DROP TABLE removes the table and its data. Confirm the database and table name first; use backups and migration review for important environments.","DROP TABLE temporary_import;","-- Review before running\nDROP TABLE IF EXISTS staging_rows;","-- Safer first step: inspect instead\nSELECT name FROM sqlite_master WHERE type='table';","It removes the table and its rows","It only removes duplicate rows","It renames the table","DROP TABLE removes the table contents and definition."],
    ["sql-alter-table","Changing a Table with ALTER TABLE","Evolve a schema through deliberate, engine-aware migrations.","ALTER TABLE changes an existing table, but supported operations vary by database and version. SQLite supports common operations such as rename and add column; complex changes may require a create-copy-swap migration.","ALTER TABLE learners ADD COLUMN email TEXT;","ALTER TABLE courses RENAME TO classes;","-- Check engine support before changing constraints\nALTER TABLE products ADD COLUMN active INTEGER NOT NULL DEFAULT 1;","Available operations depend on the database engine and version","Every ALTER TABLE operation is portable","ALTER TABLE only changes query output","Schema-change support varies among engines."],
    ["sql-constraints","Using Constraints for Valid Data","Let the database enforce rules that every stored row must follow.","Constraints protect data even when it is written by different parts of an application. Common rules include NOT NULL, UNIQUE, PRIMARY KEY, FOREIGN KEY, CHECK, and DEFAULT values.","CREATE TABLE users (id INTEGER PRIMARY KEY, email TEXT UNIQUE);","CREATE TABLE seats (number INTEGER CHECK (number > 0));","CREATE TABLE tasks (state TEXT NOT NULL DEFAULT 'open');","Constraints reject or shape invalid data","Constraints only change colors","Constraints are query aliases","Constraints enforce data rules at the database boundary."],
    ["sql-not-null","Requiring a Value with NOT NULL","Prevent a column from storing a missing value.","NOT NULL requires each inserted or updated row to provide a value for that column, subject to a default. It does not mean the value must be non-empty; use an additional CHECK when that is required.","CREATE TABLE learners (name TEXT NOT NULL);","CREATE TABLE messages (body TEXT NOT NULL DEFAULT '');","UPDATE learners SET name='Noor' WHERE id=4;","NOT NULL prevents a NULL value","NOT NULL prevents empty text in every case","NOT NULL makes a column unique","An empty string is different from NULL."],
    ["sql-unique","Preventing Duplicate Values with UNIQUE","Require values or value combinations to be unique.","UNIQUE rejects duplicate values for the constrained key. NULL treatment can differ among engines; use NOT NULL too when every row must supply a unique value.","CREATE TABLE accounts (email TEXT NOT NULL UNIQUE);","CREATE TABLE codes (region TEXT, code TEXT, UNIQUE(region,code));","CREATE UNIQUE INDEX unique_slug ON articles(slug);","It prevents duplicate constrained values","It requires values to be sorted","It creates an automatic backup","UNIQUE enforces uniqueness for a key."],
    ["sql-primary-key","Identifying Rows with a Primary Key","Give each table row a stable identifier.","A primary key uniquely identifies rows and cannot be NULL. A table can use one column or a composite key; choose values that remain stable as business details change.","CREATE TABLE learners (id INTEGER PRIMARY KEY, name TEXT NOT NULL);","CREATE TABLE course_tags (course_id INTEGER, tag_id INTEGER, PRIMARY KEY(course_id,tag_id));","SELECT id,name FROM learners WHERE id=7;","A primary key identifies a row uniquely","A primary key stores only images","A table must have three primary keys","Primary keys uniquely identify records."],
    ["sql-foreign-key","Connecting Tables with Foreign Keys","Require a reference to point to a valid row in another table.","A foreign key links child rows to a referenced key and can block orphan references. Referential actions such as cascade must be chosen carefully; SQLite applications must enable foreign-key enforcement on connections.","CREATE TABLE enrollments (learner_id INTEGER REFERENCES learners(id));","CREATE TABLE orders (customer_id INTEGER, FOREIGN KEY(customer_id) REFERENCES customers(id));","PRAGMA foreign_keys = ON;","It enforces a relationship to a referenced key","It makes all columns primary keys","It automatically merges two tables","Foreign keys protect relational consistency."],
    ["sql-check","Validating Values with CHECK","Reject rows that fail a boolean rule.","CHECK evaluates a condition for inserted or updated values. Use it for simple domain rules such as a positive quantity, while remembering NULL can make a condition unknown rather than false.","CREATE TABLE stock (quantity INTEGER CHECK(quantity >= 0));","CREATE TABLE ratings (score INTEGER CHECK(score BETWEEN 1 AND 5));","CREATE TABLE users (role TEXT CHECK(role IN ('student','teacher')));","It validates a condition on stored values","It sorts results","It adds a missing column","CHECK is a row validity rule."],
    ["sql-default","Providing a Default with DEFAULT","Supply a value when an insert omits a column.","DEFAULT provides a value when the INSERT statement leaves that column out. An explicit NULL is not always replaced by the default; define NOT NULL separately if missing values are disallowed.","CREATE TABLE tasks (state TEXT DEFAULT 'open');","CREATE TABLE visits (count INTEGER NOT NULL DEFAULT 0);","INSERT INTO tasks DEFAULT VALUES;","It supplies a value when an insert omits the column","It rewrites old rows on every query","It forces all values to be unique","A default applies when a value is omitted."],
    ["sql-create-index","Indexing Columns for Lookup","Add an index to help selected searches and ordering patterns.","An index can speed reads that filter or join on indexed columns, at the cost of storage and extra work during writes. Use query plans and workload evidence rather than indexing every column.","CREATE INDEX idx_orders_customer ON orders(customer_id);","CREATE UNIQUE INDEX idx_users_email ON users(email);","CREATE INDEX idx_events_time_type ON events(created_at,event_type);","Indexes can speed lookups but add write/storage costs","Indexes always speed every query","Indexes replace all constraints","Index design depends on query workload."],
    ["sql-auto-increment","Generating Integer Keys","Use the database's supported mechanism to create row identifiers.","Auto-generated key syntax varies. SQLite commonly uses INTEGER PRIMARY KEY for a row identifier; AUTOINCREMENT has specific behavior and is not needed for most tables. Other engines use IDENTITY or AUTO_INCREMENT forms.","-- SQLite\nCREATE TABLE learners (id INTEGER PRIMARY KEY, name TEXT);","-- MySQL\nCREATE TABLE learners (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100));","-- SQL Server\nCREATE TABLE learners (id INT IDENTITY(1,1) PRIMARY KEY, name NVARCHAR(100));","Key-generation syntax varies by engine","Every database requires the word AUTOINCREMENT","Generated keys are always text","Use the syntax supported by the selected database."],
    ["sql-dates","Working with Dates and Times","Store and compare temporal values consistently.","Date and time storage differs across engines. SQLite commonly stores ISO-8601 text, Julian day numbers, or Unix timestamps; other engines offer native date/time types. Use clear time zones and half-open ranges for periods.","SELECT * FROM events WHERE starts_at >= '2026-04-01' AND starts_at < '2026-05-01';","SELECT date(created_at) AS day, COUNT(*) FROM visits GROUP BY date(created_at);","INSERT INTO events (starts_at) VALUES ('2026-04-15T09:30:00Z');","Date storage and functions vary by engine","All dates should be stored in local display format","Date strings sort randomly","Consistent formats and timezone handling make date comparisons reliable."],
    ["sql-views","Saving a Query as a View","Expose a reusable query through a named database object.","A view stores a query definition rather than a separate copy of its result in many engines. It can simplify repeated joins and restrict exposed columns, but it is not automatically a security boundary by itself.","CREATE VIEW active_learners AS SELECT id,name FROM learners WHERE active=1;","SELECT name FROM active_learners ORDER BY name;","DROP VIEW active_learners;","A view is a named query definition","A view always stores a second physical copy","A view is a database password","Views can make repeated query logic reusable."],
  ]),
  ...extras("Safe Queries and Database Practice", [
    ["sql-injection","Preventing SQL Injection","Keep untrusted input from becoming SQL syntax.","SQL injection occurs when application input is joined directly into query text. Use prepared statements with bound values, validate allowed choices, and limit database permissions.","db.prepare('SELECT * FROM users WHERE email = ?').get(email);","cur.execute('SELECT * FROM courses WHERE level = ?', (level,))","Allowlist sort keys and bind filter values","Use parameterized statements for user-provided values","Escape quotes by hand and concatenate values","Trust browser validation alone","Bound parameters keep values separate from SQL structure."],
    ["sql-parameters","Supplying Query Parameters","Pass values separately from SQL text.","A parameter is a placeholder whose value is supplied by the database driver. Placeholder syntax varies; parameters represent values, not table or column names.","SELECT * FROM learners WHERE id = ?;","SELECT * FROM products WHERE category = :category;","UPDATE tasks SET state = $1 WHERE id = $2;","Parameters bind values separately from SQL text","Parameters automatically select any table name","Parameters replace WHERE","Drivers bind values with engine-specific placeholders."],
    ["sql-prepared-statements","Prepared Statements","Execute queries with safely bound values.","Prepared statements separate query structure from data and can be reused. They help prevent injection for values; dynamic identifiers still need an allowlist.","const stmt = db.prepare('SELECT * FROM learners WHERE id = ?'); stmt.get(id);","cur.execute('SELECT * FROM courses WHERE level = ?', (level,))","stmt.run('open'); stmt.run('closed');","Values are supplied separately from query structure","They make unsafe concatenation safe automatically","They parameterize arbitrary column names","Prepared statements bind values safely."],
    ["sql-stored-procedures","Stored Procedures","Understand server-side routines and engine differences.","A stored procedure is a named routine available in some database servers. Syntax varies, and SQLite has no stored procedures; application code or triggers are alternatives.","-- SQL Server style\nCREATE PROCEDURE ListLearners AS SELECT id,name FROM learners;","-- MySQL style\nCREATE PROCEDURE ListCourses() SELECT id,title FROM courses;","-- SQLite application query\nSELECT id,name FROM learners WHERE active = ?;","Support and syntax depend on the database","Every engine uses identical procedure syntax","A procedure is an index","Stored routines are not portable across all SQL engines."],
    ["sql-hosting","Database Hosting Basics","Plan secure access, backups, and recovery.","A database may run locally, on managed hosting, or on infrastructure you operate. Plan for access control, secret storage, updates, backups, monitoring, and restore practice.","Keep local database files outside public folders","Read connection strings from a secret manager","Test restoring a backup regularly","Secure credentials and tested backups matter","Publish passwords in source code","Expose database ports to everyone","Hosting needs secure access and recovery planning."],
    ["sql-mysql-dialect","MySQL Dialect","Recognize MySQL-specific syntax and functions.","MySQL has its own types, functions, and administrative syntax. Translate deliberately instead of assuming examples run unchanged in another engine.","SELECT name FROM learners LIMIT 5;","SELECT IFNULL(phone, 'Unknown') FROM contacts;","CREATE TABLE users (id INT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(200));","MySQL syntax can differ from other engines","MySQL queries always run unchanged everywhere","IFNULL is the only SQL function","Dialect-aware translation is needed."],
    ["sql-sqlserver-dialect","SQL Server Dialect","Recognize features such as TOP and IDENTITY.","SQL Server has T-SQL features and functions. TOP limits rows in this dialect; ordering should be explicit when the chosen rows matter.","SELECT TOP (5) name FROM learners ORDER BY name;","SELECT ISNULL(phone, 'Unknown') FROM contacts;","CREATE TABLE users (id INT IDENTITY(1,1) PRIMARY KEY, email NVARCHAR(200));","TOP and IDENTITY are SQL Server-oriented syntax","SQL Server uses SQLite rowid for every feature","All functions are universal","These examples use SQL Server conventions."],
    ["sql-msaccess-dialect","Microsoft Access Dialect","Identify Access-specific functions and query conventions.","Access SQL is tailored to its database engine and has dialect-specific functions. Adapt examples before using them with another database.","SELECT TOP 5 Name FROM Learners ORDER BY Name;","SELECT IIf([Active], 'Yes', 'No') AS Status FROM Learners;","SELECT Nz([Phone], 'Unknown') FROM Contacts;","Access has engine-specific expressions","Every Access function is standard SQL","Access has exactly SQLite's data model","Access syntax should be identified as dialect-specific."],
    ["sql-editor-and-tools","Using a SQL Editor","Run and inspect queries against the intended database.","A SQL editor connects to a database and shows query results. Confirm the selected connection before changes; use transactions or a practice database for destructive commands.","SELECT name FROM sqlite_master WHERE type='table';","SELECT * FROM learners WHERE active=0;","BEGIN; UPDATE learners SET active=1 WHERE id=3; ROLLBACK;","Check the connection and preview risky changes","Run DROP statements on production to test","Store credentials in shared query files","Verify the connection and target before editing data."],
    ["sql-practice","SQL Examples and Practice","Build queries from realistic data questions.","Identify source tables, choose columns, filter rows, and add joins or groups only when needed. Inspect sample data and query output to verify your answer.","SELECT title FROM courses WHERE level='beginner' ORDER BY title;","SELECT course_id,COUNT(*) FROM enrollments GROUP BY course_id;","SELECT c.id FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id=c.id);","Build from a data question and verify output","Add every clause whether needed or not","Guess without checking data","Small verified examples build reliable query habits."],
    ["sql-study-plan","SQL Study Plan","Progress from basic queries to design and safe data access.","Study SELECT and filtering, then joins, aggregation, constraints, transactions, and parameterized application queries. Revisit each skill with a small project and sample records.","SELECT title FROM courses WHERE level='beginner';","SELECT level,COUNT(*) FROM courses GROUP BY level;","CREATE TABLE enrollments (learner_id INTEGER REFERENCES learners(id));","Progress from queries to data design and safe access","Begin with procedures before SELECT","Skip database constraints","A staged plan covers queries, design, and safety."],
    ["sql-data-types-reference","Common SQL Data Types","Compare numeric, text, and temporal type families.","Common families include integer, decimal, text, boolean-like, and date/time values. Names and enforcement vary; SQLite uses flexible type affinity while some engines enforce types strictly.","CREATE TABLE items (quantity INTEGER, label TEXT);","CREATE TABLE items (quantity INT, label NVARCHAR(100));","CREATE TABLE items (quantity INT, label VARCHAR(100));","Data types and enforcement vary across engines","VARCHAR means exactly the same thing everywhere","A date must always be an integer","Choose types for the target engine."],
    ["sql-function-reference","SQL Function Families","Recognize aggregate, text, numeric, and NULL-handling functions.","Names and edge cases vary between engines. Common ideas include COUNT/SUM/AVG/MIN/MAX, string transforms, rounding, date operations, and COALESCE.","SELECT COUNT(*), AVG(score) FROM results;","SELECT UPPER(name), LENGTH(name) FROM learners;","SELECT COALESCE(phone,'Not listed') FROM contacts;","Functions are grouped by the values they process","Every engine has identical function names","Functions only return tables","Function catalogs are dialect-specific."],
    ["sql-quick-reference","SQL Quick Reference Patterns","Review patterns for selection, grouping, and joins.","Keep a reference of tested patterns and note the target database. A concise query should make its source, conditions, and expected output clear.","SELECT column FROM table WHERE condition;","SELECT key,COUNT(*) FROM table GROUP BY key HAVING COUNT(*)>1;","SELECT a.name,b.label FROM a JOIN b ON b.id=a.b_id;","Record engine assumptions with useful patterns","Assume all engines accept the same syntax","Copy without understanding tables","A useful reference includes context and dialect."],
    ["sql-server","SQL Server Overview","Understand SQL Server and its T-SQL dialect.","SQL Server is a relational database system; T-SQL adds product-specific syntax and administration. Learn core relational ideas, then identify features tied to this engine.","SELECT TOP (10) * FROM dbo.Learners ORDER BY LearnerId;","SELECT ISNULL(Phone, 'Unknown') FROM dbo.Contacts;","CREATE TABLE dbo.Tasks (Id INT IDENTITY(1,1) PRIMARY KEY, State NVARCHAR(20));","T-SQL includes SQL Server-specific features","SQL Server is a JavaScript framework","All T-SQL is portable","Separate relational concepts from dialect features."],
  ]),
  ...extras("Assessment and Projects", [
    ["sql-certificate-prep","SQL Certificate Preparation","Review core SQL skills with a structured self-check.","Prepare by practicing query reading, filtering, joins, aggregation, schema constraints, NULL behavior, and safe parameter use. This lesson provides an original study path and practice patterns rather than linking to an external certification provider.","SELECT department,COUNT(*) FROM staff GROUP BY department;","SELECT c.name FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id=c.id);","CREATE TABLE tasks (id INTEGER PRIMARY KEY, title TEXT NOT NULL);","Review both query skills and data design","Study only function names","Skip hands-on practice","A balanced review includes querying, design, and safe access."],
    ["sql-code-challenges","SQL Code Challenges","Solve small problems that combine multiple SQL concepts.","Write a query for each task, run it on sample rows, and check boundary cases. Explain your reasoning and improve readability after the result is correct.","SELECT p.name FROM products p WHERE p.price > (SELECT AVG(price) FROM products WHERE category=p.category);","SELECT l.name FROM learners l WHERE NOT EXISTS (SELECT 1 FROM enrollments e WHERE e.learner_id=l.id);","SELECT strftime('%Y-%m',paid_at),COUNT(*) FROM invoices WHERE status='paid' GROUP BY strftime('%Y-%m',paid_at);","Challenges combine concepts and should be verified on sample data","A query is correct if it looks short","Ignore NULL and boundary cases","Running the query helps validate the reasoning."],
    ["sql-learning-project","SQL Practice Project","Apply SQL concepts to a small relational dataset.","Design a compact schema, add a few realistic rows, then answer questions with filters, joins, groups, and subqueries. Finish by adding constraints and checking that invalid data is rejected.","CREATE TABLE members (id INTEGER PRIMARY KEY, name TEXT NOT NULL);","CREATE TABLE enrollments (member_id INTEGER REFERENCES members(id), course TEXT NOT NULL);","SELECT course,COUNT(*) FROM enrollments GROUP BY course ORDER BY course;","A project combines schema design with query practice","Create one huge table for unrelated data","Skip checking query output","Small connected tables help practice relational thinking."],
  ]),
];
